const item = $input.first().json;
const attachments = item.attachments || [];
const hasAudio = attachments.some(a => ['audio','voice','audio/ogg','audio/mpeg'].includes(a.type || a.mime_type));
const hasImage = attachments.some(a => ['image','image/jpeg','image/png','image/jpg'].includes(a.type || a.mime_type));
const hasDocument = attachments.some(a => ['document','application/pdf','text/plain','application/msword'].includes(a.type || a.mime_type));
const audioAttachment = hasAudio ? attachments.find(a => ['audio','voice','audio/ogg','audio/mpeg'].includes(a.type || a.mime_type)) : null;
const imageAttachment = hasImage ? attachments.find(a => ['image','image/jpeg','image/png','image/jpg'].includes(a.type || a.mime_type)) : null;
const docAttachment = hasDocument ? attachments.find(a => ['document','application/pdf','text/plain','application/msword'].includes(a.type || a.mime_type)) : null;
return [{
  json: {
    ...item,
    _attachment_type: hasAudio ? 'audio' : (hasImage ? 'image' : (hasDocument ? 'document' : 'none')),
    _audio_url: audioAttachment ? (audioAttachment.url || audioAttachment.link || '') : '',
    _image_url: imageAttachment ? (imageAttachment.url || imageAttachment.link || '') : '',
    _doc_url: docAttachment ? (docAttachment.url || docAttachment.link || '') : '',
    _doc_mime: docAttachment ? (docAttachment.mime_type || docAttachment.type || 'application/octet-stream') : ''
  }
}];

const item = $input.first().json;
const transcribed = item.text || '';
return [{ json: { ...item, transcribed_text: transcribed, message: (item.message || '') + ' [Audio transcrito]: ' + transcribed } }];

const item = $input.first().json;
const binary = $input.first().binary?.data;
let docText = '';
if (binary && binary.data) {
  try {
    docText = Buffer.from(binary.data, 'base64').toString('utf-8').substring(0, 8000);
  } catch (e) {
    docText = '[No se pudo extraer texto del documento]';
  }
} else {
  docText = '[Documento sin contenido accesible]';
}
return [{ json: { ...item, document_text: docText, message: (item.message || '') + ' [Documento]: ' + docText.substring(0, 500) } }];

const item = $input.first().json;
const transcribed = item.transcribed_text || '';
const imgCtx = item.image_context || '';
const docCtx = item.document_text || '';
const baseMsg = item.message || '';
let enrichedMsg = baseMsg;
if (imgCtx) enrichedMsg += '\n' + imgCtx;
if (docCtx && docCtx.length > 10) enrichedMsg += '\n[Documento adjunto]: ' + docCtx.substring(0, 400);

const lower = String(baseMsg || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const asksSlack = /\bslack\b/.test(lower) && /(send|envi|manda|mensaje|say hi|escribe|avisa)/.test(lower);
const asksEmail = /(email|correo)/.test(lower) && /(send|envi|manda|escribe)/.test(lower);
const asksWeb = /(web|internet|google|tavily|busca|buscar|busqueda|búsqueda|search)/.test(lower) && /(busca|buscar|search|investiga|consulta|encuentra|haz|puedes hacer)/.test(lower);
const actionIntent = asksSlack ? 'slack_send' : (asksEmail ? 'email_send' : (asksWeb ? 'web_search' : 'none'));

const emails = [...new Set(String(baseMsg || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])].map(e => e.toLowerCase());
const toEmail = emails[0] || String(item.email || '').trim().toLowerCase();
const ccEmails = emails.slice(toEmail ? 1 : 0).filter(e => e !== toEmail);

// Hard runtime contract injected per turn for action intents.
let actionDirective = '';
if (actionIntent === 'slack_send') {
  actionDirective = '[ACTION_DIRECTIVE] Debes ejecutar una tool de Slack en este turno. Primero intenta resolver destinatario/canal. Si falla la resolucion, usa canal fallback all-lev-innovation. Nunca responder sin intento de tool. Reporta error tecnico real si falla.';
}
if (actionIntent === 'email_send') {
  let directivePayload = '{"to":"' + toEmail + '","subject":"[LEV] Resumen de Agentyx","html":"<html><body><p>Resumen generado aqui</p></body></html>","from":"me"';
  if (ccEmails.length > 0) {
    directivePayload += ',"cc":' + JSON.stringify(ccEmails);
  }
  directivePayload += '}';
  actionDirective = '[ACTION_DIRECTIVE] Debes llamar la herramienta Resend Send Email Tool INMEDIATAMENTE con SOLO estos campos exactos: ' + directivePayload + '. El campo "from" siempre es "me". Usa "html" para el cuerpo HTML. Pasa SOLO estos campos: to, from, subject, html, y cc (si hay). NUNCA incluyas bcc, text, react, headers, reply_to, ni scheduled_at.';
}
if (actionIntent === 'web_search') {
  actionDirective = '[ACTION_DIRECTIVE] Debes ejecutar una tool Tavily en este turno y devolver hallazgos concretos (fuente/resumen).';
}
if (actionDirective) enrichedMsg += '\n' + actionDirective;

// Store full context for downstream CRM processing (avoids cross-node reference hang)
const context = { ...item, enriched_message: enrichedMsg, action_intent: actionIntent, email_to: toEmail, email_cc: ccEmails };


return [{ json: context }];

// Direct input access (Code v2 compatible)
let base = $input.first().json || {};
const ai = $input.first().json || {};
const text = String(base.original_user_message || base.message || base.enriched_message || '').toLowerCase();
const isActionIntent = ((/(slack|email|correo)/.test(text) && /(send|envi|manda|mensaje|say hi|escribe)/.test(text)) || (/(web|internet|google|tavily|busca|buscar|search|búsqueda)/.test(text)));
const out = String(ai.output || ai.text || '').trim();
const looksIncapacity = /(no puedo|no tengo la capacidad|no tengo acceso para enviar|te recomiendo que env[ií]es|sugiero que env[ií]es|no tengo acceso a tavily|no puedo realizar búsquedas web en tiempo real|parece que no has enviado un mensaje específico|parece que no has enviado ningún mensaje)/i.test(out);
const isGenericGreeting = /(¿en qué puedo ayudarte hoy\??|hola.{0,40}soy\s+levi)/i.test(out);
if (isActionIntent && looksIncapacity) {
  ai.output = 'Intenté ejecutar la acción vía MCP pero no se completó en este turno. Reintento sugerido con parámetros más específicos (destinatario/canal o consulta web concreta).';
}
if (!isActionIntent && isGenericGreeting && text.length > 12) {
  ai.output = 'Entendido. Estoy procesando tu solicitud sobre LEV Innovation y te respondo con detalle en este mismo turno. Si aplica, incluiré recursos shareable disponibles.';
}
if (text.length > 3 && /parece que no has enviado (un mensaje específico|ningún mensaje)/i.test(out)) {
  if (/(tools?|herramientas|integraciones|acceso).*(tienes|puedes)|que tools tienes|qué tools tienes|qué herramientas tienes|que herramientas tienes/i.test(text)) {
    ai.output = 'Actualmente puedo usar estas herramientas cuando están habilitadas: Resend (enviar correos), Google Calendar (eventos), Slack (mensajes), búsqueda web (Tavily), Google Drive y acciones de CRM (Twenty), además de búsqueda en la base de conocimiento de LEV Innovation.';
  } else {
    ai.output = 'Recibí tu mensaje correctamente. Te respondo de forma concreta: puedo ayudarte con información comercial, capacidades y próximos pasos sobre las soluciones de LEV Innovation.';
  }
}
const isDocAsk = /(archivo|pdf|deck|brochure|documento|shareable|adjuntar|mandar|enviar)/i.test(text);
const hasKb = String(base.kb_context || '').trim().length > 80;
const deniesShareable = /(no tengo (un )?archivo shareable|no tengo archivos shareable|no tengo acceso a archivos específicos)/i.test(out);
if (isDocAsk && hasKb && deniesShareable) {
  ai.output = 'Sí tengo contexto documental relevante de LEV Innovation en la base de conocimiento. Puedo resumirte y estructurar ese material ahora mismo; si necesitas el archivo original (PDF/deck) como adjunto descargable, te lo gestiono con escalamiento inmediato al equipo humano para envío directo.';
}
const asksAttachment = /(adjunto|adjuntar|attachment|pdf|deck|pasamelo|pásamelo|envíalo)/i.test(text);
const docs = Array.isArray(base.shareable_documents) ? base.shareable_documents : [];
const portalDoc = docs.find(d => String(d.doc_id || '').trim());
const tenant = String(base.tenant_slug || ((base.metadata || {}).tenant_slug) || 'levinnovation');
const generatedDownloadUrl = portalDoc
  ? `https://webhooks.n8n.agentyx.one/webhook/documents/download?tenant=${encodeURIComponent(tenant)}&doc_id=${encodeURIComponent(String(portalDoc.doc_id || ''))}`
  : (asksAttachment
      ? `https://webhooks.n8n.agentyx.one/webhook/documents/download?tenant=${encodeURIComponent(tenant)}`
      : '');
const urlMatches = Array.from(new Set(String(base.kb_context || '').match(/https?:\/\/[^\s)]+/g) || []));
const fallbackUrl = urlMatches.find(u => /\.(pdf|pptx?|docx?|xlsx?|zip)(\?|$)/i.test(u)) || urlMatches[0] || '';
const attachmentUrl = generatedDownloadUrl || fallbackUrl;
const deniesAttachment = /(no puedo enviar documentos adjuntos|no puedo enviar adjuntos|no tengo acceso a archivos|no tengo archivos shareable|no tengo un archivo shareable)/i.test(out);
if (asksAttachment && attachmentUrl) {
  ai.attachment_url = attachmentUrl;
  ai.send_attachment = true;
  ai.attachment_caption = 'Adjunto solicitado por el usuario.';
  ai.reply_attachments = [{
    type: 'document',
    url: attachmentUrl,
    caption: String(ai.attachment_caption || 'Adjunto solicitado por el usuario.')
  }];
  if (!out || deniesAttachment || looksIncapacity) {
    ai.output = 'Te comparto el documento como adjunto ahora.';
  }
}
return [{ json: { ...base, ...ai } }];

const template = $input.first().json || {};
const item = $input.first().json || {};
const userMessage = String(item.original_user_message || item.message || item.enriched_message || '').trim();
const templateHtml = String(template.html || template.email_template_html || '').trim();
const templateRule = 'If you call Resend send, convert markdown body to valid HTML, inject it into template placeholder {{body_html}}, and pass the resulting HTML via the html field.';
const lower = userMessage.toLowerCase();
const needsEmailTemplate = String(item.action_intent || '') === 'email_send' || /(email|correo)/i.test(lower);

let enriched = String(item.enriched_message || userMessage || '').trim();
if (!enriched && userMessage) enriched = userMessage;
if (templateHtml && needsEmailTemplate) {
  enriched += `\n\n[EMAIL_TEMPLATE_HTML]\n${templateHtml.slice(0, 6000)}\n\n[EMAIL_TEMPLATE_RULE]\n${templateRule}`;
}

return [{
  json: {
    ...item,
    original_user_message: userMessage,
    message: userMessage,
    enriched_message: enriched,
    email_template_html: templateHtml,
    email_template_from_name: String(template.fromName || ''),
    email_template_subject_prefix: String(template.subjectPrefix || ''),
    email_template_logo_url: String(template.logoUrl || ''),
    email_template_brand: template.brand || {},
    email_template_variables: template.variables || {}
  }
}];

const item = $input.first();
const data = item.json || {};
const templateHtml = String(data.email_template_html || data.html || "").trim();
const markdownCandidate = String(data.generated_email_markdown || data.message || data.enriched_message || "").trim();
const fallbackBody = markdownCandidate
  ? `<p style="margin:0 0 12px 0;">${markdownCandidate.replace(/\n/g, "<br />")}</p>`
  : `<p style="margin:0;">No body content provided.</p>`;
const htmlBody = templateHtml && templateHtml.includes("{{body_html}}")
  ? templateHtml.replace(/\{\{body_html\}\}/g, fallbackBody)
  : fallbackBody;
return [{ json: { ...data, template_intercept_applied: true, intercepted_email_html: htmlBody, composio_email_payload: { body: htmlBody, is_html: true } } }];

const ai = $input.first().json || {};
const replyText = String(ai.reply_text || ai.output || ai.text || '').trim();

return [{
  json: {
    reply_text: replyText,
    reply_attachments: Array.isArray(ai.reply_attachments) ? ai.reply_attachments : [],
    ok: true
  }
}];

